<?php use Hls\Http\View as V; ?>
<?php if($error): ?><div class="alert alert-error"><?= V::escape($error) ?></div><?php endif ?>
<?php if($access->can('finance.account.manage')): ?><section class="panel"><h2>Tambah Rekening</h2><form method="post" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="action" value="save"><label>Kode<input name="code" maxlength="40" required></label><label>Nama<input name="name" maxlength="160" required></label><label>Jenis<select name="account_type"><option value="CASH">Kas</option><option value="BANK">Bank</option></select></label><label>Mata uang<input name="currency" value="IDR" maxlength="3" required></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code'].' - '.$b['name']) ?></option><?php endif; endforeach ?></select></label><label>Status<select name="active"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></label><button class="button button-primary" type="submit">Simpan</button></form></section><?php endif ?>
<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Jenis</th><th>Cabang</th><th>Saldo berjalan</th><th>Status</th><?php if($access->can('finance.account.manage')):?><th>Aksi</th><?php endif ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= V::escape($row['code']) ?></td><td><?= V::escape($row['name']) ?></td><td><?= V::escape($row['account_type']) ?></td> class="status-badge <?= $row['active']?'':'inactive' ?>"><?= $row['active']?'Aktif':'Nonaktif' ?></span></td><?php if($access->can('finance.account.manage')):?><td><form method="post" style="display:inline"><?= $this->csrf() ?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="version" value="<?= (int)$row['version'] ?>"><input type="hidden" name="active" value="<?= $row['active']?0:1 ?>"><button type="submit" class="button button-small"><?= $row['active']?'Nonaktifkan':'Aktifkan' ?></button></form></td><?php endif ?></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada rekening.</p><?php endif ?></div></section>
